-- One premium coffee bar; keep historical basic orders and their product reference.
BEGIN;
UPDATE public.products SET is_active=false, updated_at=now() WHERE id='c211cedd-ef93-4dba-9a6e-b2edb1add6e0';
UPDATE public.products p SET variations=(SELECT jsonb_agg(CASE WHEN v->>'type'='addons' THEN jsonb_set(v,'{items}',
  COALESCE((SELECT jsonb_agg(a ORDER BY n) FROM jsonb_array_elements(v->'items') WITH ORDINALITY z(a,n) WHERE COALESCE(a->>'bar_syrup','') NOT IN ('caramel','vanilla','sugar')),'[]'::jsonb) || '[{"name": "Caramel syrup", "name_he": "סירופ קרמל", "bar_syrup": "caramel", "price": 59, "max": 6}, {"name": "Vanilla syrup", "name_he": "סירופ וניל", "bar_syrup": "vanilla", "price": 59, "max": 6}, {"name": "Sugar syrup", "name_he": "סירופ סוכר", "bar_syrup": "sugar", "price": 59, "max": 6}]'::jsonb) ELSE v END ORDER BY pos)
  FROM jsonb_array_elements(p.variations) WITH ORDINALITY t(v,pos)),updated_at=now()
WHERE id='9361ff6e-4227-44cc-a23a-428a002f1f4c';
INSERT INTO public.products (id,name_en,name_he,description_en,description_he,category,price,images,is_active,is_subscription,is_coffee_bar,sort_order,delivery_price,variations) VALUES ('46dc3b6a-37a5-4c49-a12d-566a43fd4c39','Sugar syrup + 25 cups & 25 straws','סירופ סוכר + 25 כוסות ו־25 קשיות','25 elegant, extra-large 500 ml cups and sturdy straws + sugar syrup that mixes easily into cold coffee.','25 כוסות גדולות ואלגנטיות של 500 מ״ל וקשיות איכותיות + סירופ סוכר שמתערבב בקלות בקפה קר.','coffeebars',59,ARRAY['/bar/studio/sugar-serving-kit.svg']::text[],true,false,false,201,NULL,'[{"type": "serving_pack", "cups": 25, "straws": 25, "cup_ml": 500, "sugar_syrup": 1}, {"type": "ops_settings", "exclude": false, "stock_key": "sugar_syrup"}]'::jsonb) ON CONFLICT(id) DO UPDATE SET name_en=excluded.name_en,name_he=excluded.name_he,description_en=excluded.description_en,description_he=excluded.description_he,category=excluded.category,price=excluded.price,images=excluded.images,is_active=excluded.is_active,is_subscription=excluded.is_subscription,is_coffee_bar=excluded.is_coffee_bar,sort_order=excluded.sort_order,delivery_price=excluded.delivery_price,variations=excluded.variations,updated_at=now();
INSERT INTO public.products (id,name_en,name_he,description_en,description_he,category,price,images,is_active,is_subscription,is_coffee_bar,sort_order,delivery_price,variations) VALUES ('9e1abc84-b3b8-40e0-a23c-3bfbeb8602f4','25 cups & 25 straws','25 כוסות ו־25 קשיות','25 elegant, extra-large 500 ml cups and sturdy straws — ready to serve your coffee.','25 כוסות גדולות ואלגנטיות של 500 מ״ל וקשיות איכותיות — להגשת הקפה שלכם.','coffeebars',19.99,ARRAY['/bar/studio/cups-straws-pack.svg']::text[],true,false,false,202,NULL,'[{"type": "serving_pack", "cups": 25, "straws": 25, "cup_ml": 500, "sugar_syrup": 0}, {"type": "ops_settings", "exclude": true, "stock_key": ""}]'::jsonb) ON CONFLICT(id) DO UPDATE SET name_en=excluded.name_en,name_he=excluded.name_he,description_en=excluded.description_en,description_he=excluded.description_he,category=excluded.category,price=excluded.price,images=excluded.images,is_active=excluded.is_active,is_subscription=excluded.is_subscription,is_coffee_bar=excluded.is_coffee_bar,sort_order=excluded.sort_order,delivery_price=excluded.delivery_price,variations=excluded.variations,updated_at=now();
COMMIT;
